/* Roti Pagi Bakery — Vanilla JS. Demo mode uses localStorage; Supabase mode uses supabase-config.js. */
const $ = (s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(n)||0);
const dateID=s=>s?new Date(`${String(s).slice(0,10)}T00:00:00`).toLocaleDateString('id-ID',{day:'2-digit',month:'short',year:'numeric'}):'—';
const monthID=s=>s?new Date(`${String(s).slice(0,7)}-01T00:00:00`).toLocaleDateString('id-ID',{month:'long',year:'numeric'}):'—';
const isoToday=()=>new Date().toLocaleDateString('en-CA');
const periodNow=()=>isoToday().slice(0,7)+'-01';
const id=()=>crypto.randomUUID?crypto.randomUUID():`id-${Date.now()}-${Math.random().toString(16).slice(2)}`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials=s=>String(s||'RP').split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const DEPARTMENTS=['Produksi Adonan','Pemanggangan','Dekorasi dan Finishing','Pengemasan','Gudang Bahan Baku','Distribusi','Administrasi','Supervisor Produksi'];
const STATUSES=['Hadir','Izin','Sakit','Alpha','Libur']; const PRODUCTS=['Roti Tawar','Roti Manis','Roti Cokelat','Roti Keju','Donat','Croissant','Roti Sobek'];
const TITLES={dashboard:'Dashboard',employees:'Data Karyawan',attendance:'Absensi & Lembur',production:'Data Produksi',incentives:'Insentif Karyawan',payroll:'Penggajian',slips:'Slip Gaji & Laporan',settings:'Pengaturan'};
const blankData=()=>({employees:[],attendance:[],production:[],payrolls:[],products:PRODUCTS.map((n,i)=>({id:`p${i+1}`,product_code:`PRD-${String(i+1).padStart(3,'0')}`,product_name:n,incentive_rate:[150,200,225,225,175,300,250][i],status:'Aktif'})),settings:{company_name:'Roti Pagi Bakery',company_address:'Jl. Pagi Ceria No. 12, Semarang',regular_hours_per_day:8,overtime_rate_per_hour:0,fixed_allowance:0,attendance_bonus:0,absence_deduction_per_day:0,bpjs_deduction:0,income_tax_deduction:0}});
function demoSeed(){const d=blankData();d.employees=[
{id:'e1',employee_code:'RBP-001',full_name:'Aditya Pratama',position:'Baker',department:'Produksi Adonan',employment_type:'Tetap',join_date:'2023-03-15',base_salary:4200000,phone:'081234560001',status:'Aktif'},
{id:'e2',employee_code:'RBP-002',full_name:'Siti Aulia',position:'Operator Oven',department:'Pemanggangan',employment_type:'Tetap',join_date:'2023-05-02',base_salary:4000000,phone:'081234560002',status:'Aktif'},
{id:'e3',employee_code:'RBP-003',full_name:'Bima Saputra',position:'Staf Pengemasan',department:'Pengemasan',employment_type:'Kontrak',join_date:'2024-01-10',base_salary:3600000,phone:'081234560003',status:'Aktif'},
{id:'e4',employee_code:'RBP-004',full_name:'Nadia Putri',position:'Petugas Gudang',department:'Gudang Bahan Baku',employment_type:'Tetap',join_date:'2022-11-21',base_salary:3800000,phone:'081234560004',status:'Aktif'},
{id:'e5',employee_code:'RBP-005',full_name:'Rizky Maulana',position:'Sopir Distribusi',department:'Distribusi',employment_type:'Tetap',join_date:'2023-07-01',base_salary:3900000,phone:'081234560005',status:'Aktif'},
{id:'e6',employee_code:'RBP-006',full_name:'Dinda Maharani',position:'Staf Administrasi',department:'Administrasi',employment_type:'Tetap',join_date:'2022-08-17',base_salary:4300000,phone:'081234560006',status:'Aktif'}];
const day=isoToday();d.attendance=[['e1','Hadir',8,2],['e2','Hadir',8,1],['e3','Hadir',8,0],['e4','Izin',0,0],['e5','Hadir',8,1],['e6','Hadir',8,0]].map((a,i)=>({id:`a${i+1}`,employee_id:a[0],attendance_date:day,attendance_status:a[1],regular_hours:a[2],overtime_hours:a[3],notes:''}));
d.production=[{id:'pr1',employee_id:'e1',production_date:day,product_type:'Roti Manis',quantity_produced:1000,quantity_accepted:950,incentive_rate:200,notes:'Shift pagi'},{id:'pr2',employee_id:'e2',production_date:day,product_type:'Roti Tawar',quantity_produced:800,quantity_accepted:770,incentive_rate:150,notes:'Shift pagi'},{id:'pr3',employee_id:'e3',production_date:day,product_type:'Donat',quantity_produced:600,quantity_accepted:570,incentive_rate:175,notes:'Shift pagi'},{id:'pr4',employee_id:'e1',production_date:day,product_type:'Roti Cokelat',quantity_produced:400,quantity_accepted:385,incentive_rate:225,notes:''}];
const p=periodNow();d.payrolls=d.employees.slice(0,4).map((e,i)=>{const incentive=d.production.filter(x=>x.employee_id===e.id&&x.production_date.slice(0,7)===p.slice(0,7)).reduce((s,x)=>s+x.quantity_accepted*x.incentive_rate,0);const overtime=d.attendance.filter(x=>x.employee_id===e.id&&x.attendance_date.slice(0,7)===p.slice(0,7)).reduce((s,x)=>s+x.overtime_hours,0)*0;const gross=e.base_salary+incentive+overtime;return {id:`pay${i+1}`,payroll_number:`PAY-${p.slice(0,7).replace('-','')}-${String(i+1).padStart(3,'0')}`,employee_id:e.id,period_month:p,base_salary:e.base_salary,fixed_allowance:0,attendance_bonus:0,overtime_pay:overtime,production_incentive:incentive,absence_deduction:0,other_deductions:0,bpjs_deduction:0,income_tax_deduction:0,gross_pay:gross,total_deductions:0,net_pay:gross,status:i===0?'Dibayar':i===1?'Disetujui':'Draft',paid_at:i===0?new Date().toISOString():null,calculation_snapshot:{full_name:e.full_name,employee_code:e.employee_code,position:e.position,department:e.department}}});return d;}
let state={page:'dashboard',mode:'demo',data:blankData(),filterPeriod:periodNow(),search:'',modal:null};
function loadDemo(){try{const s=localStorage.getItem('rbp_demo_data');if(s)state.data=JSON.parse(s);else{state.data=demoSeed();saveDemo();}}catch{state.data=demoSeed();}state.mode='demo';}
function saveDemo(){if(state.mode==='demo')localStorage.setItem('rbp_demo_data',JSON.stringify(state.data));}
function notify(message,type='success'){const el=document.createElement('div');el.className=`toast ${type==='error'?'error':''}`;el.innerHTML=`<i class="fa-solid ${type==='error'?'fa-circle-exclamation':'fa-circle-check'}"></i><span>${esc(message)}</span>`;$('#toastRoot').append(el);setTimeout(()=>el.remove(),3800);}
function failMessage(e){return e?.message||'Terjadi kesalahan yang tidak diketahui.'}
function employee(id){return state.data.employees.find(e=>e.id===id)||{};}
function filteredPeriod(s,period=state.filterPeriod){return String(s||'').slice(0,7)===String(period).slice(0,7);}
function activeEmployees(){return state.data.employees.filter(e=>e.status==='Aktif');}
function periodProduction(){return state.data.production.filter(p=>filteredPeriod(p.production_date));}
function periodAttendance(){return state.data.attendance.filter(a=>filteredPeriod(a.attendance_date));}
function periodPayroll(){return state.data.payrolls.filter(p=>filteredPeriod(p.period_month));}
function incentiveFor(empId,period){return state.data.production.filter(p=>p.employee_id===empId&&filteredPeriod(p.production_date,period)).reduce((s,p)=>s+Number(p.quantity_accepted)*Number(p.incentive_rate),0);}
function hoursFor(empId,period){return state.data.attendance.filter(a=>a.employee_id===empId&&filteredPeriod(a.attendance_date,period)).reduce((s,a)=>s+Number(a.overtime_hours||0),0);}
function calcPayroll(e,period,overrides={}){const s=state.data.settings;const rows=state.data.attendance.filter(a=>a.employee_id===e.id&&filteredPeriod(a.attendance_date,period));const absences=rows.filter(a=>a.attendance_status==='Alpha').length;const attendanceBonus=rows.length>0&&rows.every(a=>['Hadir','Libur'].includes(a.attendance_status))?Number(s.attendance_bonus||0):0;const vals={base_salary:Number(e.base_salary)||0,fixed_allowance:Number(s.fixed_allowance)||0,attendance_bonus,overtime_pay:hoursFor(e.id,period)*Number(s.overtime_rate_per_hour||0),production_incentive:incentiveFor(e.id,period),absence_deduction:absences*Number(s.absence_deduction_per_day||0),other_deductions:0,bpjs_deduction:Number(s.bpjs_deduction||0),income_tax_deduction:Number(s.income_tax_deduction||0),...overrides};vals.gross_pay=vals.base_salary+vals.fixed_allowance+vals.attendance_bonus+vals.overtime_pay+vals.production_incentive;vals.total_deductions=vals.absence_deduction+vals.other_deductions+vals.bpjs_deduction+vals.income_tax_deduction;vals.net_pay=vals.gross_pay-vals.total_deductions;return vals;}
function statusBadge(s){const c=s==='Dibayar'||s==='Aktif'||s==='Hadir'?'green':s==='Disetujui'||s==='Izin'||s==='Sakit'?'orange':s==='Alpha'||s==='Tidak Aktif'?'red':'gray';return `<span class="badge badge-${c}">${esc(s||'—')}</span>`;}
function pageHeading(title,desc,actions=''){return `<div class="page-heading"><div><h2>${title}</h2><p>${desc}</p></div><div class="actions">${actions}</div></div>`;}
function periodFilter(){return `<div class="filter-row"><input type="month" class="field filter-field" id="periodFilter" value="${esc(state.filterPeriod.slice(0,7))}" aria-label="Pilih periode"></div>`;}
function stat(label,value,icon,foot='Ringkasan periode terpilih'){return `<div class="stat-card"><div class="stat-top"><span>${label}</span><span class="stat-icon"><i class="fa-solid ${icon}"></i></span></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`;}
function tableEmpty(msg='Belum ada data',sub='Tambahkan data baru untuk mulai mencatat aktivitas.'){return `<div class="empty-state"><i class="fa-solid fa-bread-slice"></i><b>${msg}</b><p>${sub}</p></div>`;}
function table(headers,rows,emptyMsg){return `<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||''}</tbody></table></div>${!rows?tableEmpty(emptyMsg):''}`;}
function personCell(e){return `<div class="person-cell"><span class="person-avatar">${esc(initials(e.full_name))}</span><span><span class="person-name">${esc(e.full_name||'Karyawan dihapus')}</span><span class="person-meta">${esc(e.employee_code||'')}</span></span></div>`;}
function dashboard(){const p=state.filterPeriod,pa=periodPayroll(),prod=state.data.production.filter(x=>filteredPeriod(x.production_date,p)),att=state.data.attendance.filter(x=>filteredPeriod(x.attendance_date,p));const totalNet=pa.reduce((s,x)=>s+Number(x.net_pay||0),0),totalInc=prod.reduce((s,x)=>s+x.quantity_accepted*x.incentive_rate,0),totalOT=att.reduce((s,a)=>s+a.overtime_hours,0)*Number(state.data.settings.overtime_rate_per_hour||0),unpaid=pa.filter(x=>x.status!=='Dibayar'),totalUnits=prod.reduce((s,x)=>s+Number(x.quantity_produced),0);
const monthly=Array.from({length:6},(_,i)=>{const dt=new Date(`${p.slice(0,7)}-01T00:00:00`);dt.setMonth(dt.getMonth()-(5-i));const key=dt.toLocaleDateString('en-CA').slice(0,7);return {label:dt.toLocaleDateString('id-ID',{month:'short'}),value:state.data.payrolls.filter(x=>String(x.period_month).slice(0,7)===key).reduce((s,x)=>s+Number(x.net_pay||0),0)}});const max=Math.max(1,...monthly.map(x=>x.value));
const products=PRODUCTS.map(name=>({name,total:prod.filter(x=>x.product_type===name).reduce((s,x)=>s+x.quantity_produced,0)})).filter(x=>x.total).sort((a,b)=>b.total-a.total);const leaders=[...new Set(prod.map(x=>x.employee_id))].map(eid=>({e:employee(eid),total:prod.filter(x=>x.employee_id===eid).reduce((s,x)=>s+x.quantity_accepted*x.incentive_rate,0)})).sort((a,b)=>b.total-a.total).slice(0,4);const recent=[...state.data.payrolls].sort((a,b)=>String(b.created_at||b.period_month).localeCompare(String(a.created_at||a.period_month))).slice(0,5);
return `${pageHeading('Selamat datang kembali 👋','Ringkasan aktivitas pabrik dan penggajian Roti Pagi Bakery.',periodFilter())}<div class="stats-grid">${stat('Karyawan Aktif',activeEmployees().length,'fa-users',`${state.data.employees.length} total karyawan terdaftar`)}${stat('Total Gaji Bersih',money(totalNet),'fa-wallet',`${pa.length} slip pada periode ini`)}${stat('Total Insentif Produksi',money(totalInc),'fa-award','Dari produk yang lolos standar kualitas')}${stat('Total Biaya Lembur',money(totalOT),'fa-clock','Estimasi dari jam lembur tercatat')}${stat('Penggajian Belum Dibayar',`${unpaid.length} <span style="font-size:13px;color:#9B8376">slip</span>`,'fa-file-invoice-dollar',money(unpaid.reduce((s,x)=>s+Number(x.net_pay||0),0))+' belum dibayar')}${stat('Total Produksi Roti',new Intl.NumberFormat('id-ID').format(totalUnits),'fa-wheat-awn','Unit diproduksi pada periode ini')}</div>
<div class="content-grid"><section class="panel"><div class="panel-head"><div><h3 class="panel-title">Tren Penggajian</h3><p class="panel-subtitle">Gaji bersih tersimpan · 6 bulan terakhir</p></div><span class="badge badge-orange"><i class="fa-solid fa-chart-column"></i> Rupiah</span></div><div class="panel-body"><div class="chart-area">${monthly.map(m=>`<div class="bar-group"><span class="bar-value">${m.value?new Intl.NumberFormat('id-ID',{notation:'compact',maximumFractionDigits:1}).format(m.value):'—'}</span><div class="bar" style="height:${m.value?Math.max(5,m.value/max*130):3}px"></div><span class="bar-label">${m.label}</span></div>`).join('')}</div></div></section><section class="panel"><div class="panel-head"><div><h3 class="panel-title">Produksi per Jenis Roti</h3><p class="panel-subtitle">Total unit produksi pada periode terpilih</p></div><i class="fa-solid fa-bread-slice" style="color:var(--caramel)"></i></div><div class="panel-body"><div class="product-bars">${products.length?products.slice(0,6).map(x=>`<div class="product-line"><span>${esc(x.name)}</span><div class="progress"><span style="width:${Math.max(3,x.total/Math.max(...products.map(y=>y.total))*100)}%"></span></div><b>${new Intl.NumberFormat('id-ID').format(x.total)}</b></div>`).join(''):tableEmpty('Belum ada produksi')}</div></div></section></div>
<div class="content-grid"><section class="panel"><div class="panel-head"><div><h3 class="panel-title">Insentif Produksi Tertinggi</h3><p class="panel-subtitle">Berdasarkan catatan produksi periode ini</p></div><button class="btn btn-sm" data-page="incentives">Lihat semua <i class="fa-solid fa-arrow-right"></i></button></div>${leaders.length?table(['Karyawan','Departemen','Total insentif'],leaders.map(x=>`<tr><td>${personCell(x.e)}</td><td>${esc(x.e.department||'—')}</td><td><b>${money(x.total)}</b></td></tr>`).join('')):tableEmpty('Belum ada data insentif')}</section><section class="panel"><div class="panel-head"><div><h3 class="panel-title">Penggajian Terbaru</h3><p class="panel-subtitle">Riwayat penggajian terakhir</p></div><button class="btn btn-sm" data-page="payroll">Lihat semua <i class="fa-solid fa-arrow-right"></i></button></div>${recent.length?table(['Karyawan','Periode','Gaji bersih','Status'],recent.map(x=>`<tr><td>${personCell({...employee(x.employee_id),...(x.calculation_snapshot||{})})}</td><td>${monthID(x.period_month)}</td><td><b>${money(x.net_pay)}</b></td><td>${statusBadge(x.status)}</td></tr>`).join('')):tableEmpty('Belum ada penggajian')}</section></div>
<section class="panel"><div class="panel-head"><div><h3 class="panel-title">Status Penggajian Periode Ini</h3><p class="panel-subtitle">Progres persetujuan dan pembayaran</p></div></div><div class="panel-body"><div class="summary-strip">${['Draft','Disetujui','Dibayar'].map(s=>`<div class="summary-box"><span>${s}</span><b>${pa.filter(x=>x.status===s).length} penggajian</b></div>`).join('')}</div></div></section>`;}
function employeeRows(){let list=state.data.employees.filter(e=>`${e.full_name} ${e.employee_code}`.toLowerCase().includes(state.search.toLowerCase()));const dept=$('#deptFilter')?.value||'';const status=$('#empStatusFilter')?.value||'';if(dept)list=list.filter(e=>e.department===dept);if(status)list=list.filter(e=>e.status===status);return list.map(e=>`<tr><td>${personCell(e)}</td><td>${esc(e.position)}</td><td>${esc(e.department)}</td><td>${money(e.base_salary)}</td><td>${statusBadge(e.status)}</td><td><div class="table-actions"><button class="icon-btn" title="Detail" data-action="detail-employee" data-id="${e.id}"><i class="fa-regular fa-eye"></i></button><button class="icon-btn" title="Edit" data-action="edit-employee" data-id="${e.id}"><i class="fa-solid fa-pen"></i></button><button class="icon-btn" title="Nonaktifkan/hapus" data-action="delete-employee" data-id="${e.id}"><i class="fa-solid fa-user-slash"></i></button></div></td></tr>`).join('');}
function employeesPage(){return `${pageHeading('Data Karyawan','Kelola identitas, jabatan, dan gaji pokok karyawan pabrik.',`<button class="btn btn-primary" data-action="add-employee"><i class="fa-solid fa-plus"></i> Tambah Karyawan</button>`)}<div class="panel"><div class="table-toolbar"><div class="search-wrap"><i class="fa-solid fa-search"></i><input class="field" id="searchInput" placeholder="Cari nama atau kode karyawan…" value="${esc(state.search)}"></div><div class="filter-row"><select class="select filter-field" id="deptFilter"><option value="">Semua departemen</option>${DEPARTMENTS.map(x=>`<option>${x}</option>`).join('')}</select><select class="select filter-field" id="empStatusFilter"><option value="">Semua status</option><option>Aktif</option><option>Tidak Aktif</option></select></div></div>${table(['Karyawan','Jabatan','Departemen','Gaji pokok','Status','Aksi'],employeeRows(),'Belum ada karyawan')}<div class="table-foot"><span id="rowCount">${state.data.employees.length} karyawan terdaftar</span><span>Data dikelola oleh administrator</span></div></div>`;}
function attendancePage(){const list=state.data.attendance.filter(a=>`${employee(a.employee_id).full_name||''} ${employee(a.employee_id).employee_code||''}`.toLowerCase().includes(state.search.toLowerCase())&&(!$('#attDateFilter')?.value||a.attendance_date===$('#attDateFilter').value));const rows=list.map(a=>`<tr><td>${dateID(a.attendance_date)}</td><td>${personCell(employee(a.employee_id))}</td><td>${statusBadge(a.attendance_status)}</td><td>${a.regular_hours} jam</td><td><b>${a.overtime_hours} jam</b></td><td>${esc(a.notes||'—')}</td><td><div class="table-actions"><button class="icon-btn" data-action="edit-attendance" data-id="${a.id}" title="Edit"><i class="fa-solid fa-pen"></i></button><button class="icon-btn" data-action="delete-attendance" data-id="${a.id}" title="Hapus"><i class="fa-solid fa-trash"></i></button></div></td></tr>`).join('');const sum= s=>list.filter(a=>a.attendance_status===s).length;return `${pageHeading('Absensi & Lembur','Catat kehadiran harian dan jam lembur setiap karyawan.',`<button class="btn btn-primary" data-action="add-attendance"><i class="fa-solid fa-plus"></i> Catat Absensi</button>`)}<div class="summary-strip">${['Hadir','Izin','Sakit','Alpha'].map(s=>`<div class="summary-box"><span>${s}</span><b>${sum(s)} catatan</b></div>`).join('')}</div><div class="panel"><div class="table-toolbar"><div class="search-wrap"><i class="fa-solid fa-search"></i><input class="field" id="searchInput" placeholder="Cari karyawan…" value="${esc(state.search)}"></div><input type="date" id="attDateFilter" class="field filter-field" value=""></div>${table(['Tanggal','Karyawan','Status','Jam reguler','Jam lembur','Catatan','Aksi'],rows,'Belum ada catatan absensi')}<div class="table-foot"><span>${list.length} catatan ditampilkan</span><span>Total lembur: ${list.reduce((s,a)=>s+Number(a.overtime_hours),0)} jam</span></div></div>`;}
function productionPage(){const list=state.data.production.filter(p=>`${employee(p.employee_id).full_name||''} ${p.product_type}`.toLowerCase().includes(state.search.toLowerCase()));const rows=list.map(p=>`<tr><td>${dateID(p.production_date)}</td><td>${personCell(employee(p.employee_id))}</td><td>${esc(p.product_type)}</td><td>${Number(p.quantity_produced).toLocaleString('id-ID')}</td><td><b>${Number(p.quantity_accepted).toLocaleString('id-ID')}</b></td><td>${money(p.incentive_rate)}</td><td><b>${money(p.quantity_accepted*p.incentive_rate)}</b></td><td><div class="table-actions"><button class="icon-btn" data-action="edit-production" data-id="${p.id}" title="Edit"><i class="fa-solid fa-pen"></i></button><button class="icon-btn" data-action="delete-production" data-id="${p.id}" title="Hapus"><i class="fa-solid fa-trash"></i></button></div></td></tr>`).join('');return `${pageHeading('Data Produksi Roti','Catat jumlah produksi dan unit yang lolos pemeriksaan kualitas.',`<button class="btn btn-primary" data-action="add-production"><i class="fa-solid fa-plus"></i> Tambah Produksi</button>`)}<div class="summary-strip"><div class="summary-box"><span>Total unit diproduksi</span><b>${list.reduce((s,p)=>s+Number(p.quantity_produced),0).toLocaleString('id-ID')}</b></div><div class="summary-box"><span>Lolos standar kualitas</span><b>${list.reduce((s,p)=>s+Number(p.quantity_accepted),0).toLocaleString('id-ID')}</b></div><div class="summary-box"><span>Insentif terhitung</span><b>${money(list.reduce((s,p)=>s+p.quantity_accepted*p.incentive_rate,0))}</b></div><div class="summary-box"><span>Catatan produksi</span><b>${list.length}</b></div></div><div class="panel"><div class="table-toolbar"><div class="search-wrap"><i class="fa-solid fa-search"></i><input class="field" id="searchInput" placeholder="Cari karyawan atau produk…" value="${esc(state.search)}"></div><button class="btn" data-action="manage-products"><i class="fa-solid fa-sliders"></i> Tarif Produk</button></div>${table(['Tanggal','Karyawan','Jenis roti','Diproduksi','Lolos QC','Tarif/unit','Insentif','Aksi'],rows,'Belum ada catatan produksi')}<div class="table-foot"><span>${list.length} catatan produksi</span><span>Insentif hanya dihitung dari unit lolos QC</span></div></div>`;}
function incentivesPage(){const list=state.data.production.filter(p=>filteredPeriod(p.production_date));const groups={};for(const p of list){const key=p.employee_id+'|'+p.product_type;if(!groups[key])groups[key]={employee_id:p.employee_id,product_type:p.product_type,produced:0,accepted:0,rate:p.incentive_rate,total:0};groups[key].produced+=Number(p.quantity_produced);groups[key].accepted+=Number(p.quantity_accepted);groups[key].total+=Number(p.quantity_accepted)*Number(p.incentive_rate);}const rows=Object.values(groups).sort((a,b)=>b.total-a.total).map(x=>`<tr><td>${personCell(employee(x.employee_id))}</td><td>${esc(employee(x.employee_id).department||'—')}</td><td>${esc(x.product_type)}</td><td>${x.produced.toLocaleString('id-ID')}</td><td>${x.accepted.toLocaleString('id-ID')}</td><td>${money(x.rate)}</td><td><b>${money(x.total)}</b></td></tr>`).join('');return `${pageHeading('Insentif Karyawan','Perhitungan transparan berdasarkan jumlah produk yang lolos standar kualitas.',periodFilter())}<div class="summary-strip"><div class="summary-box"><span>Total insentif</span><b>${money(list.reduce((s,p)=>s+p.quantity_accepted*p.incentive_rate,0))}</b></div><div class="summary-box"><span>Produk lolos QC</span><b>${list.reduce((s,p)=>s+p.quantity_accepted,0).toLocaleString('id-ID')} unit</b></div><div class="summary-box"><span>Karyawan terlibat</span><b>${new Set(list.map(p=>p.employee_id)).size}</b></div><div class="summary-box"><span>Rumus</span><b>Unit lolos × tarif</b></div></div><div class="panel">${table(['Karyawan','Departemen','Jenis roti','Diproduksi','Lolos standar','Tarif/unit','Total insentif'],rows,'Belum ada data insentif')}<div class="table-foot"><span>Periode: ${monthID(state.filterPeriod)}</span><span>Insentif dapat ditelusuri ke catatan produksi</span></div></div>`;}
function payrollPage(){const list=state.data.payrolls.filter(p=>filteredPeriod(p.period_month)&&(`${employee(p.employee_id).full_name||p.calculation_snapshot?.full_name||''} ${employee(p.employee_id).employee_code||p.calculation_snapshot?.employee_code||''} ${p.payroll_number}`).toLowerCase().includes(state.search.toLowerCase()));const rows=list.map(p=>{const e={...employee(p.employee_id),...(p.calculation_snapshot||{})};return `<tr><td><b>${esc(p.payroll_number)}</b><div class="person-meta">${monthID(p.period_month)}</div></td><td>${personCell(e)}</td><td>${money(p.gross_pay)}</td><td>${money(p.total_deductions)}</td><td><b>${money(p.net_pay)}</b></td><td>${statusBadge(p.status)}</td><td><div class="table-actions"><button class="icon-btn" data-action="view-payroll" data-id="${p.id}" title="Detail"><i class="fa-regular fa-eye"></i></button>${p.status==='Draft'?`<button class="icon-btn" data-action="approve-payroll" data-id="${p.id}" title="Setujui"><i class="fa-solid fa-check"></i></button>`:''}${p.status==='Disetujui'?`<button class="icon-btn" data-action="pay-payroll" data-id="${p.id}" title="Tandai dibayar"><i class="fa-solid fa-money-bill-wave"></i></button>`:''}<button class="icon-btn" data-action="slip-payroll" data-id="${p.id}" title="Slip gaji"><i class="fa-solid fa-print"></i></button></div></td></tr>`;}).join('');const listPeriod=state.data.payrolls.filter(p=>filteredPeriod(p.period_month));return `${pageHeading('Penggajian Bulanan','Buat, tinjau, setujui, dan tandai pembayaran gaji karyawan.',`<button class="btn btn-primary" data-action="generate-payroll"><i class="fa-solid fa-calculator"></i> Buat Penggajian</button>`)}<div class="summary-strip"><div class="summary-box"><span>Total penghasilan bersih</span><b>${money(listPeriod.reduce((s,p)=>s+p.net_pay,0))}</b></div><div class="summary-box"><span>Draft</span><b>${listPeriod.filter(p=>p.status==='Draft').length}</b></div><div class="summary-box"><span>Disetujui</span><b>${listPeriod.filter(p=>p.status==='Disetujui').length}</b></div><div class="summary-box"><span>Dibayar</span><b>${listPeriod.filter(p=>p.status==='Dibayar').length}</b></div></div><div class="panel"><div class="table-toolbar"><div class="search-wrap"><i class="fa-solid fa-search"></i><input class="field" id="searchInput" placeholder="Cari nomor atau karyawan…" value="${esc(state.search)}"></div>${periodFilter()}</div>${table(['Nomor / Periode','Karyawan','Penghasilan kotor','Potongan','Gaji bersih','Status','Aksi'],rows,'Belum ada penggajian untuk periode ini')}<div class="table-foot"><span>${list.length} data penggajian</span><span>Gaji yang dibayar dikunci dari perubahan biasa</span></div></div>`;}
function slipsPage(){const list=state.data.payrolls.filter(p=>filteredPeriod(p.period_month));const rows=list.map(p=>{const e={...employee(p.employee_id),...(p.calculation_snapshot||{})};return `<tr><td>${personCell(e)}</td><td>${monthID(p.period_month)}</td><td>${money(p.net_pay)}</td><td>${statusBadge(p.status)}</td><td><button class="btn btn-sm" data-action="slip-payroll" data-id="${p.id}"><i class="fa-solid fa-print"></i> Lihat / Cetak</button></td></tr>`}).join('');return `${pageHeading('Slip Gaji & Laporan','Tinjau slip gaji dan ekspor ringkasan biaya tenaga kerja.',`<button class="btn btn-soft" data-action="export-report"><i class="fa-solid fa-file-csv"></i> Ekspor CSV</button>`)}<div class="panel"><div class="table-toolbar"><div><b style="font-size:12px;color:var(--choc)">Slip gaji tersimpan</b><div class="person-meta">Pilih slip untuk melihat rincian dan mencetak ke PDF.</div></div>${periodFilter()}</div>${table(['Karyawan','Periode','Gaji bersih','Status','Slip gaji'],rows,'Belum ada slip gaji')}<div class="table-foot"><span>Rekap biaya tenaga kerja: ${money(list.reduce((s,p)=>s+p.gross_pay,0))}</span><span>Total potongan: ${money(list.reduce((s,p)=>s+p.total_deductions,0))}</span></div></div><div class="section-card" style="margin-top:16px"><h3>Ringkasan per departemen</h3><p>Biaya tenaga kerja berdasarkan snapshot departemen pada saat penggajian.</p>${table(['Departemen','Jumlah karyawan','Penghasilan kotor','Insentif','Lembur'],departmentReport(list),'Belum ada data laporan')}</div>`;}
function departmentReport(list){const map={};for(const p of list){const e={...employee(p.employee_id),...(p.calculation_snapshot||{})};const dep=e.department||'Tidak diketahui';if(!map[dep])map[dep]={n:0,gross:0,inc:0,ot:0};map[dep].n++;map[dep].gross+=Number(p.gross_pay);map[dep].inc+=Number(p.production_incentive);map[dep].ot+=Number(p.overtime_pay);}return Object.entries(map).map(([dep,x])=>`<tr><td>${esc(dep)}</td><td>${x.n}</td><td>${money(x.gross)}</td><td>${money(x.inc)}</td><td>${money(x.ot)}</td></tr>`).join('');}
function settingsPage(){const s=state.data.settings;return `${pageHeading('Pengaturan','Atur identitas perusahaan dan parameter perhitungan penggajian.',`<button class="btn btn-primary" data-action="save-settings"><i class="fa-solid fa-floppy-disk"></i> Simpan Pengaturan</button>`)}<div class="settings-grid"><section class="section-card"><h3><i class="fa-solid fa-store" style="color:var(--caramel);margin-right:7px"></i>Identitas Perusahaan</h3><p>Ditampilkan pada slip gaji dan laporan.</p><div class="form-grid"><div class="form-group full"><label>Nama perusahaan</label><input class="field" id="settingCompany" value="${esc(s.company_name)}" required></div><div class="form-group full"><label>Alamat perusahaan</label><textarea class="textarea" id="settingAddress" rows="2">${esc(s.company_address)}</textarea></div></div></section><section class="section-card"><h3><i class="fa-solid fa-calculator" style="color:var(--caramel);margin-right:7px"></i>Parameter Penggajian</h3><p>Nilai awal nol perlu disesuaikan oleh administrator.</p><div class="form-grid">${[['regular_hours_per_day','Jam reguler per hari','number'],['overtime_rate_per_hour','Tarif lembur per jam (Rp)','number'],['fixed_allowance','Tunjangan tetap bulanan (Rp)','number'],['attendance_bonus','Bonus kehadiran (Rp)','number'],['absence_deduction_per_day','Potongan per hari Alpha (Rp)','number'],['bpjs_deduction','Potongan BPJS (Rp)','number'],['income_tax_deduction','Potongan PPh 21 (Rp)','number']].map(([k,l,t])=>`<div class="form-group"><label>${l}</label><input class="field setting-number" data-setting="${k}" type="${t}" min="0" step="any" value="${Number(s[k]||0)}"></div>`).join('')}</div><div class="inline-note"><b>Catatan kepatuhan:</b> Tarif lembur, BPJS, dan PPh Pasal 21 harus ditentukan berdasarkan ketentuan resmi dan kondisi karyawan yang berlaku. Nilai di sini adalah parameter manual, bukan kalkulasi kepatuhan otomatis.</div></section><section class="section-card"><h3><i class="fa-solid fa-database" style="color:var(--caramel);margin-right:7px"></i>Sumber Data</h3><p>Mode saat ini: <b>${state.mode==='demo'?'Demo lokal':'Supabase'}</b>.</p><p>${state.mode==='demo'?'Data disimpan pada localStorage browser ini. Data demo tidak masuk ke database.':'Data dibaca dan ditulis melalui Supabase. Pastikan kebijakan RLS sudah benar.'}</p><button class="btn" data-action="toggle-mode"><i class="fa-solid fa-arrows-rotate"></i> Ganti Mode Data</button><button class="btn btn-soft" data-action="reset-demo"><i class="fa-solid fa-rotate-left"></i> Reset Data Demo</button></section><section class="section-card"><h3><i class="fa-solid fa-bread-slice" style="color:var(--caramel);margin-right:7px"></i>Tarif Insentif Produk</h3><p>Tarif ini menjadi default saat catatan produksi baru dibuat. Tarif pada transaksi lama tetap disimpan.</p>${table(['Produk','Tarif/unit','Status'],state.data.products.map(p=>`<tr><td>${esc(p.product_name)}</td><td>${money(p.incentive_rate)}</td><td>${statusBadge(p.status)}</td></tr>`).join(''),'Belum ada produk')}<div style="margin-top:12px"><button class="btn" data-action="manage-products"><i class="fa-solid fa-pen"></i> Kelola Tarif Produk</button></div></section></div>`;}
function render(){const root=$('#pageContent');$('#pageTitle').textContent=TITLES[state.page]||'Dashboard';$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));const fn={dashboard,employees:employeesPage,attendance:attendancePage,production:productionPage,incentives:incentivesPage,payroll:payrollPage,slips:slipsPage,settings:settingsPage}[state.page]||dashboard;root.innerHTML=fn();$('#modeNotice').classList.toggle('hidden',state.mode!=='demo'||sessionStorage.getItem('rbp_notice_dismissed')==='1');const modeLabel=$('#modeBtn');if(modeLabel)modeLabel.innerHTML=`<i class="fa-solid fa-database"></i><span>Mode ${state.mode==='demo'?'Demo':'Supabase'}</span><span class="mode-pill">${state.mode==='demo'?'DEMO':'LIVE'}</span>`;$('#periodFilter')?.addEventListener('change',e=>{state.filterPeriod=e.target.value+'-01';render();});$('#searchInput')?.addEventListener('input',e=>{state.search=e.target.value;const pos=e.target.selectionStart;render();const input=$('#searchInput');if(input){input.focus();input.setSelectionRange(pos,pos);}});['deptFilter','empStatusFilter','attDateFilter'].forEach(k=>$('#'+k)?.addEventListener('change',()=>render()));}
function selectOptions(items,selected,labels){return items.map((v,i)=>`<option value="${esc(labels?labels[i]:v)}" ${String(labels?labels[i]:v)===String(selected)?'selected':''}>${esc(v)}</option>`).join('');}
function openModal(title,subtitle,body,footer,wide=false){$('#modalRoot').innerHTML=`<div class="modal-backdrop" data-action="backdrop-close"><div class="modal ${wide?'wide':''}" role="dialog" aria-modal="true"><div class="modal-head"><div><h3>${title}</h3><p>${subtitle}</p></div><button class="modal-close" data-action="close-modal" aria-label="Tutup"><i class="fa-solid fa-xmark"></i></button></div><div class="modal-body">${body}</div><div class="modal-foot">${footer||'<button class="btn" data-action="close-modal">Tutup</button>'}</div></div></div>`;}
function field(name,label,value='',type='text',required=false,extra=''){return `<div class="form-group"><label for="f_${name}">${label}${required?' *':''}</label><input class="field" id="f_${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}></div>`;}
function employeeForm(e={}){const editing=!!e.id;const body=`<form id="employeeForm"><div class="form-grid">${field('employee_code','Kode karyawan',e.employee_code||`RBP-${String(state.data.employees.length+1).padStart(3,'0')}`,'text',true)}${field('full_name','Nama lengkap',e.full_name||'','text',true)}${field('position','Jabatan',e.position||'','text',true)}<div class="form-group"><label>Departemen *</label><select class="select" name="department" required>${selectOptions(DEPARTMENTS,e.department||DEPARTMENTS[0])}</select></div><div class="form-group"><label>Jenis hubungan kerja *</label><select class="select" name="employment_type" required>${selectOptions(['Tetap','Kontrak','Harian','Magang'],e.employment_type||'Tetap')}</select></div>${field('join_date','Tanggal masuk',e.join_date||isoToday(),'date',true)}${field('base_salary','Gaji pokok (Rp)',e.base_salary??0,'number',true,'min="0" step="1000"')}${field('phone','Nomor kontak',e.phone||'','tel',false)}<div class="form-group"><label>Status *</label><select class="select" name="status">${selectOptions(['Aktif','Tidak Aktif'],e.status||'Aktif')}</select></div></div><p class="hint">* Wajib diisi. Kode karyawan harus unik.</p></form>`;openModal(editing?'Edit Karyawan':'Tambah Karyawan','Lengkapi informasi karyawan pabrik.',body,`<button class="btn" data-action="close-modal">Batal</button><button class="btn btn-primary" data-action="submit-employee"><i class="fa-solid fa-floppy-disk"></i> Simpan Karyawan</button>`);}
function attendanceForm(a={}){const editing=!!a.id;const body=`<form id="attendanceForm"><div class="form-grid"><div class="form-group full"><label>Karyawan *</label><select class="select" name="employee_id" required>${state.data.employees.filter(e=>e.status==='Aktif'||e.id===a.employee_id).map(e=>`<option value="${e.id}" ${e.id===a.employee_id?'selected':''}>${esc(e.employee_code+' — '+e.full_name)}</option>`).join('')}</select></div>${field('attendance_date','Tanggal absensi',a.attendance_date||isoToday(),'date',true)}<div class="form-group"><label>Status kehadiran *</label><select class="select" name="attendance_status">${selectOptions(STATUSES,a.attendance_status||'Hadir')}</select></div>${field('regular_hours','Jam kerja reguler',a.regular_hours??8,'number',true,'min="0" max="24" step="0.5"')}${field('overtime_hours','Jam lembur',a.overtime_hours??0,'number',true,'min="0" max="24" step="0.5"')}<div class="form-group full"><label>Catatan</label><textarea class="textarea" name="notes" rows="2">${esc(a.notes||'')}</textarea></div></div></form>`;openModal(editing?'Edit Absensi':'Catat Absensi','Satu karyawan hanya boleh memiliki satu catatan per tanggal.',body,`<button class="btn" data-action="close-modal">Batal</button><button class="btn btn-primary" data-action="submit-attendance">Simpan Absensi</button>`);}
function productionForm(p={}){const editing=!!p.id;const body=`<form id="productionForm"><div class="form-grid"><div class="form-group full"><label>Karyawan *</label><select class="select" name="employee_id" required>${state.data.employees.filter(e=>e.status==='Aktif'||e.id===p.employee_id).map(e=>`<option value="${e.id}" ${e.id===p.employee_id?'selected':''}>${esc(e.employee_code+' — '+e.full_name)}</option>`).join('')}</select></div>${field('production_date','Tanggal produksi',p.production_date||isoToday(),'date',true)}<div class="form-group"><label>Jenis roti *</label><select class="select" name="product_type" required>${selectOptions(state.data.products.filter(x=>x.status==='Aktif').map(x=>x.product_name),p.product_type||'Roti Manis')}</select></div>${field('quantity_produced','Jumlah diproduksi',p.quantity_produced??0,'number',true,'min="0" step="1"')}${field('quantity_accepted','Jumlah lolos standar kualitas',p.quantity_accepted??0,'number',true,'min="0" step="1"')}${field('incentive_rate','Tarif insentif per unit (Rp)',p.incentive_rate??(state.data.products.find(x=>x.product_name===(p.product_type||'Roti Manis'))?.incentive_rate||0),'number',true,'min="0" step="1"')}<div class="form-group full"><label>Catatan produksi</label><textarea class="textarea" name="notes" rows="2">${esc(p.notes||'')}</textarea></div></div><div class="inline-note">Insentif dihitung dari jumlah unit yang lolos standar kualitas × tarif insentif per unit.</div></form>`;openModal(editing?'Edit Catatan Produksi':'Tambah Catatan Produksi','Pastikan jumlah lolos kualitas tidak melebihi total produksi.',body,`<button class="btn" data-action="close-modal">Batal</button><button class="btn btn-primary" data-action="submit-production">Simpan Produksi</button>`);}
function generatePayrollModal(){const body=`<form id="generatePayrollForm"><div class="form-grid"><div class="form-group"><label>Periode penggajian *</label><input class="field" name="period" type="month" value="${state.filterPeriod.slice(0,7)}" required></div><div class="form-group"><label>Karyawan</label><select class="select" name="employee_id"><option value="all">Semua karyawan aktif yang belum dibuat</option>${activeEmployees().map(e=>`<option value="${e.id}">${esc(e.employee_code+' — '+e.full_name)}</option>`).join('')}</select></div></div></form><div class="inline-note">Sistem akan menghitung gaji pokok, lembur, insentif, bonus dan potongan dari data yang tersimpan. Karyawan yang sudah memiliki penggajian pada periode tersebut akan dilewati untuk mencegah duplikasi. Tinjau parameter pengaturan sebelum membuat penggajian.</div>`;openModal('Buat Penggajian','Pilih periode untuk menghitung draf penggajian.',body,`<button class="btn" data-action="close-modal">Batal</button><button class="btn btn-primary" data-action="submit-generate-payroll"><i class="fa-solid fa-calculator"></i> Hitung & Simpan Draft</button>`);}
function payrollDetail(p){const e={...employee(p.employee_id),...(p.calculation_snapshot||{})};const body=`<div class="slip"><div class="slip-head"><div class="slip-brand"><i class="fa-solid fa-bread-slice"></i><div><h2>${esc(state.data.settings.company_name)}</h2><p>${esc(state.data.settings.company_address)}</p></div></div><div class="slip-period"><h3>RINCIAN PENGGAJIAN</h3><p>${monthID(p.period_month)} • ${esc(p.payroll_number)}</p>${statusBadge(p.status)}</div></div><div class="slip-details"><div><span>Nama karyawan</span><b>${esc(e.full_name||'—')}</b></div><div><span>Kode karyawan</span><b>${esc(e.employee_code||'—')}</b></div><div><span>Jabatan</span><b>${esc(e.position||'—')}</b></div><div><span>Departemen</span><b>${esc(e.department||'—')}</b></div></div><div class="slip-total"><div><span>Gaji pokok</span><b>${money(p.base_salary)}</b></div><div><span>Tunjangan tetap</span><b>${money(p.fixed_allowance)}</b></div><div><span>Tunjangan kehadiran</span><b>${money(p.attendance_bonus)}</b></div><div><span>Pembayaran lembur</span><b>${money(p.overtime_pay)}</b></div><div><span>Insentif produksi</span><b>${money(p.production_incentive)}</b></div><div style="border-top:1px solid #ead8c8;margin-top:5px;padding-top:9px"><span>Penghasilan kotor</span><b>${money(p.gross_pay)}</b></div><div><span>Potongan ketidakhadiran</span><b>− ${money(p.absence_deduction)}</b></div><div><span>Potongan lain-lain</span><b>− ${money(p.other_deductions)}</b></div><div><span>Potongan BPJS</span><b>− ${money(p.bpjs_deduction)}</b></div><div><span>Potongan PPh Pasal 21</span><b>− ${money(p.income_tax_deduction)}</b></div><div><span>Total potongan</span><b>− ${money(p.total_deductions)}</b></div><div class="net"><span>GAJI BERSIH</span><b>${money(p.net_pay)}</b></div></div><div class="slip-sign"><div>Karyawan</div><div>Administrasi Penggajian</div></div></div>`;openModal('Detail Penggajian',`${e.full_name||''} · ${monthID(p.period_month)}`,body,`<button class="btn" data-action="close-modal">Tutup</button><button class="btn btn-primary" data-action="print-slip"><i class="fa-solid fa-print"></i> Cetak / Simpan PDF</button>`,true);}
function productManager(){const rows=state.data.products.map(p=>`<tr><td>${esc(p.product_code)}</td><td>${esc(p.product_name)}</td><td><input class="field" style="width:120px" type="number" min="0" data-product-rate="${p.id}" value="${Number(p.incentive_rate)}"></td><td>${statusBadge(p.status)}</td><td><button class="icon-btn" data-action="toggle-product" data-id="${p.id}" title="Aktif/nonaktif"><i class="fa-solid fa-power-off"></i></button></td></tr>`).join('');const body=`${table(['Kode','Nama produk','Tarif insentif/unit','Status','Aksi'],rows)}<form id="newProductForm" style="margin-top:18px"><div class="form-grid">${field('product_code','Kode produk','PRD-'+String(state.data.products.length+1).padStart(3,'0'),'text',true)}${field('product_name','Nama produk','','text',true)}${field('incentive_rate','Tarif insentif/unit (Rp)',0,'number',true,'min="0"')}</div></form>`;openModal('Kelola Produk & Tarif','Perubahan tarif hanya berlaku untuk catatan produksi baru.',body,`<button class="btn" data-action="close-modal">Tutup</button><button class="btn btn-soft" data-action="save-product-rates">Simpan Tarif</button><button class="btn btn-primary" data-action="add-product">Tambah Produk</button>`,true);}
async function refreshSupabase(){
  if(!Supa.isConfigured()) throw new Error('URL/key Supabase belum dikonfigurasi.');
  // FIX: Supa.settings.get() menggantikan Supa.settings.all() yang tidak ada.
  // Semua promise dijalankan paralel; error individual ditangkap agar pesan jelas.
  let employees, attendance, production, payrolls, products, settingsMap;
  try {
    [employees, attendance, production, payrolls, products, settingsMap] = await Promise.all([
      Supa.employees.all(),
      Supa.attendance.all(),
      Supa.production.all(),
      Supa.payrolls.all(),
      Supa.products.all(),      // FIX: sebelumnya Supa.products tidak ada → crash
      Supa.settings.get(),      // FIX: menggunakan .get() bukan .all()
    ]);
  } catch(e) {
    // Beri pesan yang lebih spesifik agar mudah di-debug
    const msg = e?.message || String(e);
    if(msg.toLowerCase().includes('jwt') || msg.toLowerCase().includes('invalid api key'))
      throw new Error('Autentikasi Supabase gagal. Periksa SUPABASE_ANON_KEY di supabase-config.js.');
    if(msg.toLowerCase().includes('relation') || msg.toLowerCase().includes('does not exist'))
      throw new Error('Tabel tidak ditemukan di Supabase. Pastikan schema.sql sudah dijalankan di proyek Supabase Anda.');
    if(msg.toLowerCase().includes('permission') || msg.toLowerCase().includes('rls') || msg.toLowerCase().includes('policy'))
      throw new Error('Akses ditolak oleh RLS Supabase. Login terlebih dahulu atau periksa kebijakan Row Level Security.');
    throw new Error('Gagal memuat data dari Supabase: ' + msg);
  }
  state.data.employees = employees || [];
  state.data.attendance = attendance || [];
  state.data.production = (production || []).map(p => ({
    ...p,
    product_type: p.product_type || (products||[]).find(x => x.id === p.product_id)?.product_name || 'Produk',
  }));
  state.data.payrolls  = payrolls || [];
  state.data.products  = (products && products.length) ? products : blankData().products;
  // FIX: settingsMap sudah berupa { company: {...}, payroll_policy: {...} } dari settingsGet()
  const pol  = settingsMap?.payroll_policy || {};
  const comp = settingsMap?.company || {};
  state.data.settings = {
    ...blankData().settings,
    ...pol,
    company_name:    comp.name    || 'Roti Pagi Bakery',
    company_address: comp.address || '',
  };
  state.mode = 'supabase';
}
async function switchMode(){if(state.mode==='demo'){if(!Supa.isConfigured()){notify('Isi URL dan anon/publishable key di supabase-config.js terlebih dahulu.','error');return;}const session=await Supa.getSession();if(!session){openModal('Masuk ke Supabase','Data karyawan dan gaji hanya dapat diakses setelah login.',`<form id="loginForm"><div class="form-grid"><div class="form-group full"><label>Email pengguna</label><input class="field" type="email" name="email" required></div><div class="form-group full"><label>Password</label><input class="field" type="password" name="password" required></div></div><p class="hint">Buat akun pengguna di Supabase Authentication terlebih dahulu.</p></form>`,`<button class="btn" data-action="close-modal">Batal</button><button class="btn btn-primary" data-action="login-supabase">Masuk</button>`);return;}try{await refreshSupabase();render();notify('Terhubung ke Supabase.');}catch(e){notify(failMessage(e),'error');}}else{state.mode='demo';loadDemo();render();notify('Kembali ke mode demo lokal.');}}
async function saveEntity(type,row,editId){if(state.mode==='demo'){const arr=state.data[type];if(editId){const i=arr.findIndex(x=>x.id===editId);if(i>=0)arr[i]={...arr[i],...row};}else arr.unshift({id:id(),created_at:new Date().toISOString(),...row});saveDemo();return;}const api={employees:Supa.employees,attendance:Supa.attendance,production:Supa.production,payrolls:Supa.payrolls,products:Supa.products}[type];if(!api)throw new Error('Modul database tidak tersedia.');const saved=await api.save(row,editId);const arr=state.data[type];if(editId){const i=arr.findIndex(x=>x.id===editId);if(i>=0)arr[i]={...arr[i],...saved};}else arr.unshift(saved);}
async function deleteEntity(type,entityId){if(state.mode==='demo'){state.data[type]=state.data[type].filter(x=>x.id!==entityId);saveDemo();return;}const api={employees:Supa.employees,attendance:Supa.attendance,production:Supa.production,payrolls:Supa.payrolls,products:Supa.products}[type];await api.remove(entityId);state.data[type]=state.data[type].filter(x=>x.id!==entityId);}
function getForm(formId){const form=$('#'+formId);if(!form||!form.reportValidity())return null;return Object.fromEntries(new FormData(form).entries());}
function num(v){const n=Number(v);if(!Number.isFinite(n)||n<0)throw new Error('Nominal/jumlah harus berupa angka nol atau lebih.');return n;}
async function submitEmployee(){const raw=getForm('employeeForm');if(!raw)return;try{const editId=$('#employeeForm').dataset.editId||null;if(state.data.employees.some(e=>e.employee_code.toLowerCase()===raw.employee_code.trim().toLowerCase()&&e.id!==editId))throw new Error('Kode karyawan sudah digunakan.');const row={...raw,employee_code:raw.employee_code.trim(),full_name:raw.full_name.trim(),position:raw.position.trim(),base_salary:num(raw.base_salary),phone:raw.phone||null};await saveEntity('employees',row,editId);$('#modalRoot').innerHTML='';render();notify('Data karyawan berhasil disimpan.');}catch(e){notify(failMessage(e),'error');}}
async function submitAttendance(){const raw=getForm('attendanceForm');if(!raw)return;try{const editId=$('#attendanceForm').dataset.editId||null;if(state.data.attendance.some(a=>a.employee_id===raw.employee_id&&a.attendance_date===raw.attendance_date&&a.id!==editId))throw new Error('Absensi karyawan untuk tanggal tersebut sudah ada.');const row={...raw,regular_hours:num(raw.regular_hours),overtime_hours:num(raw.overtime_hours),notes:raw.notes||null};await saveEntity('attendance',row,editId);$('#modalRoot').innerHTML='';render();notify('Catatan absensi berhasil disimpan.');}catch(e){notify(failMessage(e),'error');}}
async function submitProduction(){const raw=getForm('productionForm');if(!raw)return;try{const editId=$('#productionForm').dataset.editId||null;const produced=num(raw.quantity_produced),accepted=num(raw.quantity_accepted),rate=num(raw.incentive_rate);if(!Number.isInteger(produced)||!Number.isInteger(accepted))throw new Error('Jumlah produksi harus berupa bilangan bulat.');if(accepted>produced)throw new Error('Jumlah yang lolos kualitas tidak boleh melebihi jumlah produksi.');const product=state.data.products.find(p=>p.product_name===raw.product_type);const row={employee_id:raw.employee_id,production_date:raw.production_date,product_type:raw.product_type,product_id:state.mode==='supabase'?(product?.id||null):undefined,quantity_produced:produced,quantity_accepted:accepted,incentive_rate:rate,notes:raw.notes||null};if(row.product_id===undefined)delete row.product_id;await saveEntity('production',row,editId);$('#modalRoot').innerHTML='';render();notify('Catatan produksi berhasil disimpan.');}catch(e){notify(failMessage(e),'error');}}
async function generatePayroll(){const raw=getForm('generatePayrollForm');if(!raw)return;const period=raw.period+'-01';const list=activeEmployees().filter(e=>raw.employee_id==='all'||e.id===raw.employee_id);let created=0,skipped=0;try{for(const e of list){if(state.data.payrolls.some(p=>p.employee_id===e.id&&String(p.period_month).slice(0,7)===raw.period)){skipped++;continue;}const c=calcPayroll(e,period);const row={payroll_number:`PAY-${raw.period.replace('-','')}-${e.employee_code.replace(/[^A-Za-z0-9]/g,'')}`,employee_id:e.id,period_month:period,...c,status:'Draft',paid_at:null,calculation_snapshot:{full_name:e.full_name,employee_code:e.employee_code,position:e.position,department:e.department,employment_type:e.employment_type}};try{await saveEntity('payrolls',row,null);created++;}catch(err){if(String(err.message).toLowerCase().includes('duplicate')||String(err.message).toLowerCase().includes('unique'))skipped++;else throw err;}}state.filterPeriod=period;$('#modalRoot').innerHTML='';render();notify(`${created} draf penggajian dibuat${skipped?`; ${skipped} dilewati karena sudah ada`:''}.`);}catch(e){notify('Penggajian berhenti: '+failMessage(e),'error');}}
async function updatePayrollStatus(p,status){if(p.status==='Dibayar'){notify('Penggajian yang sudah dibayar tidak dapat diubah melalui alur biasa.','error');return;}const row={...p,status,paid_at:status==='Dibayar'?new Date().toISOString():null};try{if(state.mode==='demo'){Object.assign(p,row);saveDemo();}else{await Supa.payrolls.save({status,paid_at:row.paid_at},p.id);Object.assign(p,row);}render();notify(`Status penggajian diperbarui menjadi ${status}.`);}catch(e){notify(failMessage(e),'error');}}
async function saveSettings(){try{const s={company_name:$('#settingCompany').value.trim(),company_address:$('#settingAddress').value.trim()};if(!s.company_name)throw new Error('Nama perusahaan wajib diisi.');$$('.setting-number').forEach(el=>{s[el.dataset.setting]=num(el.value);});state.data.settings={...state.data.settings,...s};if(state.mode==='demo'){saveDemo();}else{
    // FIX: Supa.settings.upsert() menggantikan pendekatan lama yang memanggil
    // Supa.settings.all() dan Supa.getClient() secara manual, yang error karena
    // Supa.settings.all tidak ada. Sekarang cukup panggil upsert dua kali paralel.
    const {company_name, company_address, ...policyObj} = s;
    await Promise.all([
      Supa.settings.upsert('company',      {name: company_name, address: company_address}, 'Identitas perusahaan'),
      Supa.settings.upsert('payroll_policy', policyObj, 'Parameter penggajian'),
    ]);
  }render();notify('Pengaturan berhasil disimpan.');}catch(e){notify(failMessage(e),'error');}}
function showSlip(p){payrollDetail(p);}
function exportCSV(){const list=state.data.payrolls.filter(p=>filteredPeriod(p.period_month));const headers=['Nomor Penggajian','Periode','Kode Karyawan','Nama','Departemen','Gaji Pokok','Tunjangan Tetap','Bonus Kehadiran','Lembur','Insentif','Potongan Ketidakhadiran','Potongan Lain','BPJS','PPh 21','Penghasilan Kotor','Total Potongan','Gaji Bersih','Status'];const rows=list.map(p=>{const e={...employee(p.employee_id),...(p.calculation_snapshot||{})};return [p.payroll_number,p.period_month,e.employee_code,e.full_name,e.department,p.base_salary,p.fixed_allowance,p.attendance_bonus,p.overtime_pay,p.production_incentive,p.absence_deduction,p.other_deductions,p.bpjs_deduction,p.income_tax_deduction,p.gross_pay,p.total_deductions,p.net_pay,p.status]});const csv=[headers,...rows].map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\r\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`rekap-penggajian-${state.filterPeriod.slice(0,7)}.csv`;a.click();URL.revokeObjectURL(a.href);notify('Laporan CSV berhasil disiapkan.');}
function confirmAction(message,yes){openModal('Konfirmasi tindakan',message,`<p style="font-size:12px;color:#765D50;line-height:1.7">${message}</p>`,`<button class="btn" data-action="close-modal">Batal</button><button class="btn btn-danger" data-action="confirm-yes">Ya, lanjutkan</button>`);$('#modalRoot .modal').dataset.confirm='1';window._confirmYes=yes;}
async function handleAction(action,el){const eid=el.dataset.id;switch(action){case 'close-modal':$('#modalRoot').innerHTML='';break;case 'add-employee':employeeForm();break;case 'edit-employee':{const e=employee(eid);employeeForm(e);$('#employeeForm').dataset.editId=eid;break;}case 'detail-employee':{const e=employee(eid);openModal('Detail Karyawan',e.full_name,`<div class="form-grid">${[['Kode',e.employee_code],['Nama',e.full_name],['Jabatan',e.position],['Departemen',e.department],['Hubungan kerja',e.employment_type],['Tanggal masuk',dateID(e.join_date)],['Gaji pokok',money(e.base_salary)],['Kontak',e.phone||'—'],['Status',e.status]].map(([k,v])=>`<div class="form-group"><label>${k}</label><div>${esc(v)}</div></div>`).join('')}</div>`,`<button class="btn" data-action="close-modal">Tutup</button><button class="btn btn-primary" data-action="edit-employee" data-id="${eid}">Edit data</button>`);break;}case 'delete-employee':{const hasHistory=state.data.attendance.some(a=>a.employee_id===eid)||state.data.production.some(p=>p.employee_id===eid)||state.data.payrolls.some(p=>p.employee_id===eid);confirmAction(hasHistory?'Karyawan memiliki riwayat transaksi. Sistem akan menonaktifkan karyawan agar riwayat tetap terjaga.':'Karyawan tidak memiliki riwayat transaksi. Hapus permanen?',async()=>{try{if(hasHistory){const e=employee(eid);if(state.mode==='demo'){e.status='Tidak Aktif';saveDemo();}else{await Supa.employees.save({status:'Tidak Aktif'},eid);e.status='Tidak Aktif';}}else await deleteEntity('employees',eid);render();notify(hasHistory?'Karyawan dinonaktifkan.':'Karyawan dihapus.');}catch(e){notify(failMessage(e),'error');}});break;}case 'add-attendance':attendanceForm();break;case 'edit-attendance':{const a=state.data.attendance.find(x=>x.id===eid);attendanceForm(a);$('#attendanceForm').dataset.editId=eid;break;}case 'delete-attendance':confirmAction('Hapus catatan absensi ini?',async()=>{try{await deleteEntity('attendance',eid);render();notify('Catatan absensi dihapus.');}catch(e){notify(failMessage(e),'error');}});break;case 'add-production':productionForm();break;case 'edit-production':{const p=state.data.production.find(x=>x.id===eid);productionForm(p);$('#productionForm').dataset.editId=eid;break;}case 'delete-production':confirmAction('Hapus catatan produksi ini? Periksa dampaknya terhadap insentif sebelum melanjutkan.',async()=>{try{await deleteEntity('production',eid);render();notify('Catatan produksi dihapus.');}catch(e){notify(failMessage(e),'error');}});break;case 'manage-products':productManager();break;case 'add-product':{const raw=getForm('newProductForm');if(!raw)return;try{if(state.data.products.some(p=>p.product_code.toLowerCase()===raw.product_code.toLowerCase()||p.product_name.toLowerCase()===raw.product_name.toLowerCase()))throw new Error('Kode atau nama produk sudah terdaftar.');const row={product_code:raw.product_code.trim(),product_name:raw.product_name.trim(),incentive_rate:num(raw.incentive_rate),status:'Aktif'};await saveEntity('products',row,null);productManager();notify('Produk ditambahkan.');}catch(e){notify(failMessage(e),'error');}break;}case 'save-product-rates':try{for(const input of $$('[data-product-rate]')){const p=state.data.products.find(x=>x.id===input.dataset.productRate);if(p){p.incentive_rate=num(input.value);if(state.mode==='supabase')await Supa.products.save({incentive_rate:p.incentive_rate},p.id);}}saveDemo();productManager();notify('Tarif produk diperbarui.');}catch(e){notify(failMessage(e),'error');}break;case 'toggle-product':{const p=state.data.products.find(x=>x.id===eid);if(p){p.status=p.status==='Aktif'?'Tidak Aktif':'Aktif';try{if(state.mode==='supabase')await Supa.products.save({status:p.status},p.id);saveDemo();productManager();}catch(e){notify(failMessage(e),'error');}}break;}case 'generate-payroll':generatePayrollModal();break;case 'submit-generate-payroll':await generatePayroll();break;case 'submit-employee':await submitEmployee();break;case 'submit-attendance':await submitAttendance();break;case 'submit-production':await submitProduction();break;case 'view-payroll':{const p=state.data.payrolls.find(x=>x.id===eid);if(p)payrollDetail(p);break;}case 'approve-payroll':{const p=state.data.payrolls.find(x=>x.id===eid);if(p)confirmAction('Setujui penggajian ini? Periksa semua komponen sebelum persetujuan.',()=>updatePayrollStatus(p,'Disetujui'));break;}case 'pay-payroll':{const p=state.data.payrolls.find(x=>x.id===eid);if(p)confirmAction('Tandai penggajian ini sebagai Dibayar? Tindakan ini akan mengunci perubahan biasa.',()=>updatePayrollStatus(p,'Dibayar'));break;}case 'slip-payroll':{const p=state.data.payrolls.find(x=>x.id===eid);if(p)showSlip(p);break;}case 'print-slip':window.print();break;case 'export-report':exportCSV();break;case 'save-settings':await saveSettings();break;case 'toggle-mode':await switchMode();break;case 'reset-demo':confirmAction('Reset seluruh data demo ke data awal? Perubahan data demo saat ini akan hilang.',()=>{localStorage.removeItem('rbp_demo_data');loadDemo();render();notify('Data demo direset.');});break;case 'confirm-yes':$('#modalRoot').innerHTML='';if(window._confirmYes){const fn=window._confirmYes;window._confirmYes=null;await fn();}break;case 'login-supabase':{const raw=getForm('loginForm');if(!raw)return;try{await Supa.signIn(raw.email,raw.password);await refreshSupabase();$('#modalRoot').innerHTML='';render();notify('Berhasil masuk ke Supabase.');}catch(e){notify(failMessage(e),'error');}break;}case 'dismiss-notice':$('#modeNotice').classList.add('hidden');sessionStorage.setItem('rbp_notice_dismissed','1');break;case 'backdrop-close':if(el.target===el)$('#modalRoot').innerHTML='';break;case 'toggle-sidebar':document.body.classList.toggle('sidebar-collapsed');break;case 'mobile-menu':$('#sidebar').classList.toggle('mobile-open');$('#mobileShade').classList.toggle('show');break;}}
function readRemoteRow(type,row){return row;}
async function init(){loadDemo();$('#todayLabel').textContent=new Date().toLocaleDateString('id-ID',{weekday:'short',day:'2-digit',month:'short',year:'numeric'});$('#yearNow').textContent=new Date().getFullYear();$('#navMenu').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b){state.page=b.dataset.page;state.search='';render();$('#sidebar').classList.remove('mobile-open');$('#mobileShade').classList.remove('show');}});document.addEventListener('click',e=>{const pageBtn=e.target.closest('[data-page]');if(pageBtn&&!pageBtn.closest('#navMenu')){state.page=pageBtn.dataset.page;state.search='';render();return;}const el=e.target.closest('[data-action]');if(el)handleAction(el.dataset.action,el);});$('#collapseBtn').addEventListener('click',()=>document.body.classList.toggle('sidebar-collapsed'));$('#mobileMenuBtn').addEventListener('click',()=>handleAction('mobile-menu',$('#mobileMenuBtn')));$('#mobileShade').addEventListener('click',()=>handleAction('mobile-menu',$('#mobileMenuBtn')));$('#modeBtn').addEventListener('click',switchMode);$('#dismissNotice').addEventListener('click',()=>handleAction('dismiss-notice',$('#dismissNotice')));render();
// If credentials exist and a valid session is already present, load connected data automatically.
if(Supa.isConfigured()){try{const session=await Supa.getSession();if(session){await refreshSupabase();render();notify('Data Supabase berhasil dimuat.');}}catch(e){console.warn('Supabase belum dimuat:',e.message);}}
}
document.addEventListener('DOMContentLoaded',init);
